from collections import Counter
import math

class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        count = Counter(tiles)
        freqs = list(count.values())

        def backtrack(index):
            if index == len(freqs):
                total = 1
                for f in freqs:
                    if f > 0:
                        total *= math.factorial(f)
                return math.factorial(sum(freqs)) // total

            current_char_count = freqs[index]
            total_ways = 0

            for k in range(1, current_char_count + 1):
                freqs[index] -= k
                total_ways += backtrack(index + 1)
                freqs[index] += k

            return total_ways

        return backtrack(0)
